#!/bin/sh
# lazyinit.sh turns the init function of each file generated by yaegi extract
# in the current directory into a loader registered with register, so that the
# symbols are only added to Symbols when Load is called (see symbols.go).
for f in $(grep -l "^// Code generated by 'yaegi extract" *.go); do
	perl -0pi -e 's/^func init\(\) \{\n(.*?)^\}\n/var _ = register(func() {\n$1})\n/sm' "$f"
done
